  enteredFromJoinRoom: boolean,
  selectedPlanId: string | undefined,
  recommendedPlanId: string | undefined,
): boolean => {
  if (!enteredFromJoinRoom) {
    return true;
  }

  return Boolean(
    selectedPlanId &&
      recommendedPlanId &&
      selectedPlanId === recommendedPlanId,
  );
};

